const summary = String(item.json.vacancy_summary ?? '').trim();
const evidence = Array.isArray(item.json.requirement_evidence) ? item.json.requirement_evidence : [];
const verifiedAt = Date.parse(item.json.requirements_verified_at ?? '');
const title = String(item.json.title ?? '').trim();
const company = String(item.json.company_name ?? '').trim();
const jobUrl = String(item.json.canonical_url ?? '').trim();
const modality = String(item.json.modality ?? 'desconocido').trim();
const text = `${title} ${summary}`.toLowerCase();
const reasons = [];
const validEvidence = evidence.filter((entry) => entry && typeof entry.requirement === 'string' && entry.requirement.trim() && /^https?:\/\/[^#\s]+$/.test(String(entry.evidence_url ?? '')) && !Number.isNaN(Date.parse(entry.verified_at ?? '')));
if (modality === 'presencial') reasons.push('presencial_o_residencia_incompatible');
if (/must be authorized to work in|no sponsorship|sin patrocinio/.test(text)) reasons.push('autorizacion_laboral_restringida');
if (/\b([4-9]|[1-9][0-9])\+?\s+years?\b|m[aá]s de 3 a[nñ]os/.test(text)) reasons.push('experiencia_requerida_supera_tres_anios');
if (!company) reasons.push('empresa_no_verificable');
if (!title) reasons.push('cargo_no_verificable');
if (!jobUrl) reasons.push('canal_de_postulacion_no_verificable');
if (summary.length < 20 || /<[^>]+>/.test(summary)) reasons.push('requirements_summary_no_verificable');
if (evidence.length === 0 || validEvidence.length !== evidence.length || Number.isNaN(verifiedAt)) reasons.push('evidencia_de_requisitos_ausente_o_invalida');
if (/pay a fee|payment required|send (your )?password|share credentials|pago requerido|env[ií]e.*contrase[nñ]a/.test(text)) reasons.push('solicitud_insegura_o_enganiosa');
if (/research scientist|ml scientist|machine learning research|deep learning researcher/.test(text)) reasons.push('investigacion_ml_avanzada_fuera_del_posicionamiento');
if (/\b(senior|staff)\b/.test(text)) reasons.push('senioridad_no_demostrable');
item.json.hard_filter_failed = reasons.length > 0;
item.json.hard_filter_reasons = reasons;
item.json.valid_requirement_evidence = validEvidence;
return item;

const data = item.json;
const summary = String(data.vacancy_summary ?? '').trim();
const title = String(data.title ?? '').toLowerCase();
const text = `${title} ${summary}`.toLowerCase();
const evidence = data.valid_requirement_evidence ?? [];
const scoredAt = new Date().toISOString();
const base = {rubric_version:'career/qualification-rubric.md', scored_at:scoredAt};
if (data.hard_filter_failed) {
  data.score = 0;
  data.route = 'discard';
  data.score_breakdown = {...base, problema_rol:{points:0,max:25,basis:'no evaluado: filtro obligatorio'}, stack_responsabilidades:{points:0,max:25,matches:[]}, evidencia_disponible:{points:0,max:15,basis:'no evaluada: filtro obligatorio'}, modalidad_elegibilidad:{points:0,max:15,basis:data.modality ?? 'desconocido'}, seniority_aprendizaje:{points:0,max:10,basis:'no evaluada: filtro obligatorio'}, ingles_colaboracion:{points:0,max:5,basis:'no evaluada: filtro obligatorio'}, empresa_oportunidad:{points:0,max:5,basis:'no evaluada: filtro obligatorio'}, total:0, decision:'discard', motivo:`filtro_obligatorio: ${data.hard_filter_reasons.join(',')}`};
  return item;
}
let problemRole = 0;
if (/ai automation|automation engineer|integration engineer|implementation specialist|automation specialist|workflow automation/.test(text)) problemRole = 25;
else if (/\b(automation|integration|implementation)\b/.test(text)) problemRole = 20;
else if (/\b(developer|operations|customer success)\b/.test(text)) problemRole = 10;
const stackParts = [['n8n_o_workflows',5,/\bn8n\b|\bworkflow/],['apis_o_webhooks',5,/\bapi\b|\bwebhooks?\b/],['llm_rag_o_agentes',4,/\bllm\b|\brag\b|\bagents?\b/],['postgres_o_supabase',4,/\bpostgres(?:ql)?\b|\bsupabase\b/],['typescript_node_o_javascript',4,/\btypescript\b|\bnode\.?js\b|\bjavascript\b/],['crm_whatsapp_o_interfaces',3,/\bcrm\b|\bwhatsapp\b|\binterfaces?\b/]];
const stackMatches = stackParts.filter(([, , pattern]) => pattern.test(text));
const stack = Math.min(25, stackMatches.reduce((sum, [, points]) => sum + points, 0));
const evidencePoints = evidence.length >= 2 ? 15 : evidence.length === 1 ? 8 : 0;
const modalityPoints = ['remoto_colombia_latam','contractor_internacional'].includes(data.modality) ? 15 : ['hibrido','desconocido'].includes(data.modality) ? 8 : 0;
const seniority = /\b(junior|associate|intern|contractor)\b/.test(text) ? 10 : /\bmid\b/.test(text) ? 5 : 0;
const english = /\b(b1|b2|intermediate english)\b/.test(text) ? 5 : /\benglish\b|\bingl[eé]s\b/.test(text) ? 2 : 0;
const companyOpportunity = data.company_name && data.canonical_url ? (evidence.length >= 2 ? 5 : evidence.length === 1 ? 2 : 0) : 0;
const total = problemRole + stack + evidencePoints + modalityPoints + seniority + english + companyOpportunity;
const route = total >= 70 ? 'research' : total >= 55 ? 'human_review' : 'discard';
data.score = total;
data.route = route;
data.score_breakdown = {...base, problema_rol:{points:problemRole,max:25,basis:problemRole ? 'titulo_y_requirements_summary_verificables':'sin_hechos_suficientes'}, stack_responsabilidades:{points:stack,max:25,matches:stackMatches.map(([name])=>name)}, evidencia_disponible:{points:evidencePoints,max:15,basis:`${evidence.length} evidencia(s) fechada(s) verificable(s)`}, modalidad_elegibilidad:{points:modalityPoints,max:15,basis:data.modality ?? 'desconocido'}, seniority_aprendizaje:{points:seniority,max:10,basis:'titulo_y_requirements_summary'}, ingles_colaboracion:{points:english,max:5,basis:'requirements_summary'}, empresa_oportunidad:{points:companyOpportunity,max:5,basis:'empresa_canal_y_evidencia_verificables'}, total, decision:route, motivo:`score_${total}; ruta_${route}; evidencia_fechada_${evidence.length}`};
return item;
